+Convexity.StdSimplex.simplexBoundary_homotopy_extension.{u, w} {X : Type u} {Y : Type w} [TopologicalSpace X]
+  [TopologicalSpace Y] (n : ℕ) (f : C(X × Convexity.StdSimplex ℝ (Fin (n + 1)), Y))
+  (H : C((X × ↑(Convexity.StdSimplex.boundary n)) × ↑unitInterval, Y))
+  (h : ∀ (x : X) (b : ↑(Convexity.StdSimplex.boundary n)), H ((x, b), 0) = f (x, ↑b)) :
+  ∃ K,
+    (∀ (x : X) (b : Convexity.StdSimplex ℝ (Fin (n + 1))), K ((x, b), 0) = f (x, b)) ∧
+      ∀ (x : X) (b : ↑(Convexity.StdSimplex.boundary n)) (t : ↑unitInterval), K ((x, ↑b), t) = H ((x, b), t)
+TopCat.homotopyExtensionProperty_simplexBoundary.{u} (X : TopCat) (n : ℕ) :
+  TopCat.HomotopyExtensionProperty (X.parameterizedSimplexBoundaryInclusion n)
+TopCat.homotopyExtensionProperty_continuous.{u} {A B : TopCat} {i : A ⟶ B} (hi : TopCat.HomotopyExtensionProperty i)
+  (Z : TopCat) (f : C(↑B, ↑Z)) (H : C(↑unitInterval × ↑A, ↑Z))
+  (hzero : ∀ (a : ↑A), H (0, a) = f ((CategoryTheory.ConcreteCategory.hom i) a)) :
+  ∃ K,
+    (∀ (b : ↑B), K (0, b) = f b) ∧
+      ∀ (t : ↑unitInterval) (a : ↑A), K (t, (CategoryTheory.ConcreteCategory.hom i) a) = H (t, a)
