+Convexity.StdSimplex.exists_simplex_boundary_track_of_faces.{u} {Z : Type u} [TopologicalSpace Z] (d : ℕ)
+  (H : Fin (d + 3) → C(Convexity.StdSimplex ℝ (Fin (d + 2)) × ↑unitInterval, Z))
+  (hfaces :
+    ∀ (i : Fin (d + 3)) (k : Fin (d + 2)) (q : Convexity.StdSimplex ℝ (Fin (d + 1))) (t : ↑unitInterval),
+      (H i) (Convexity.StdSimplex.map k.succAbove q, t) =
+        (H (i.succAbove k)) (Convexity.StdSimplex.map (k.predAbove i).succAbove q, t)) :
+  ∃ K,
+    ∀ (i : Fin (d + 3)) (x : Convexity.StdSimplex ℝ (Fin (d + 2))) (t : ↑unitInterval),
+      K ((Convexity.StdSimplex.simplexBoundaryFace (d + 1) i) x, t) = (H i) (x, t)
